styles:
/* Local scope: prevents collisions across modules */
    #cc-hero-module * { box-sizing: border-box; }

    #cc-hero-module{
      --gradient-1:#667eea;
      --gradient-2:#764ba2;
      --gradient-3:#ec4899;
      --gradient-4:#f59e0b;
      --gradient-5:#8b5cf6;
      position: relative;
      z-index: 3;
      color:#fff;
      font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
    }

    /* Background blobs */
    #cc-hero-module .bg-blobs {
      position:fixed;
      inset:0;
      overflow:hidden;
      z-index:1;
      pointer-events:none;
      filter:blur(100px) saturate(1.3);
      opacity:0.4;
    }
    #cc-hero-module .bg-blob {
      position:absolute;
      border-radius:999px;
      will-change:transform;
      mix-blend-mode:screen;
    }
    #cc-hero-module .blob-1 { width:480px;height:480px;background:var(--gradient-1);top:-80px;left:-60px; }
    #cc-hero-module .blob-2 { width:520px;height:520px;background:var(--gradient-3);top:20%;right:-120px; }
    #cc-hero-module .blob-3 { width:460px;height:460px;background:var(--gradient-4);bottom:-140px;left:10%; }
    #cc-hero-module .blob-4 { width:420px;height:420px;background:var(--gradient-5);bottom:10%;right:10%; }

    /* Grain overlay - scoped */
    #cc-hero-module::before{
      content:'';
      position:fixed;
      inset:0;
      background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 400 400' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
      opacity:.025;
      pointer-events:none;
      z-index:2;
    }

    @media (max-width: 768px) {
      #cc-hero-module .bg-blobs { filter: blur(70px) saturate(1.2); opacity: 0.32; }
    }
    @media (prefers-reduced-motion: reduce) {
      #cc-hero-module .bg-blobs { opacity: 0.3; }
    }

    /* HERO */
    #cc-hero-module .hero{
      position:relative;
      z-index:3;
      min-height:100vh;
      display:flex;
      align-items:center;
      padding:150px 80px 80px;
    }
    #cc-hero-module .hero-grid{
      max-width:1600px;
      margin:0 auto;
      width:100%;
      display:grid;
      grid-template-columns:1fr 200px;
      gap:100px;
      align-items:center;
    }
    #cc-hero-module .hero-content{ max-width:900px; }

    #cc-hero-module .badge{
      font-size:11px;
      font-weight:200;
      letter-spacing:2.5px;
      text-transform:uppercase;
      color:rgba(255,255,255,.35);
      margin-bottom:30px;
      opacity:0;
      animation:ccFadeIn 1s ease-out .2s forwards;
    }

    #cc-hero-module h1{
      font-size:clamp(3.5rem,8vw,9rem);
      font-weight:100;
      line-height:1;
      letter-spacing:-.04em;
      margin-bottom:40px;
      opacity:0;
      animation:ccFadeIn 1s ease-out .4s forwards;
    }
    #cc-hero-module h1 .line{ display:block; margin-bottom:8px; }
    #cc-hero-module h1 .gradient-word{
      font-weight:100;
      background:linear-gradient(90deg,var(--gradient-1) 0%,var(--gradient-2) 25%,var(--gradient-3) 50%,var(--gradient-4) 75%,var(--gradient-1) 100%);
      -webkit-background-clip:text;
      -webkit-text-fill-color:transparent;
      background-clip:text;
      background-size:300% 300%;
      animation:ccGradientShift 6s ease infinite;
    }
    @keyframes ccGradientShift{
      0%,100%{background-position:0% 50%}
      50%{background-position:100% 50%}
    }

    #cc-hero-module .subtitle{
      font-size:clamp(1rem,1.6vw,1.3rem);
      font-weight:100;
      line-height:1.7;
      color:rgba(255,255,255,.4);
      margin-bottom:50px;
      letter-spacing:.01em;
      opacity:0;
      animation:ccFadeIn 1s ease-out .6s forwards;
    }

    #cc-hero-module .service-tags{
      display:flex;
      gap:32px;
      flex-wrap:wrap;
      margin-bottom:50px;
      opacity:0;
      animation:ccFadeIn 1s ease-out .8s forwards;
    }
    #cc-hero-module .tag{
      font-size:13px;
      font-weight:200;
      color:rgba(255,255,255,.3);
      letter-spacing:.3px;
      position:relative;
      padding-left:14px;
      transition:color .3s ease;
    }
    #cc-hero-module .tag::before{
      content:'•';
      position:absolute;
      left:0;
      top:50%;
      transform:translateY(-50%);
      color:var(--gradient-3);
      opacity:.5;
    }
    #cc-hero-module .tag:hover{ color:rgba(255,255,255,.6); }

    #cc-hero-module .hero-cta{
      display:flex;
      gap:40px;
      opacity:0;
      animation:ccFadeIn 1s ease-out 1s forwards;
    }
    #cc-hero-module .cta-btn{
      padding:0;
      font-family:inherit;
      font-size:14px;
      font-weight:200;
      letter-spacing:1px;
      text-transform:uppercase;
      text-decoration:none;
      color:rgba(255,255,255,.85);
      position:relative;
      display:inline-block;
      transition:color .4s ease;
    }
    #cc-hero-module .cta-btn::after{
      content:'';
      position:absolute;
      bottom:-6px;
      left:0;
      width:0;
      height:1px;
      background:linear-gradient(90deg,var(--gradient-2),var(--gradient-3),var(--gradient-4));
      transition:width .5s cubic-bezier(.4,0,.2,1);
    }
    #cc-hero-module .cta-btn:hover{ color:#fff; }
    #cc-hero-module .cta-btn:hover::after{ width:100%; }

    #cc-hero-module .stats-sidebar{
      display:flex;
      flex-direction:column;
      gap:80px;
      opacity:0;
      animation:ccFadeIn 1s ease-out 1s forwards;
    }
    #cc-hero-module .stat-item{ text-align:right; }
    #cc-hero-module .stat-number{
      font-size:3.5rem;
      font-weight:100;
      display:block;
      background:linear-gradient(135deg,var(--gradient-2) 0%,var(--gradient-3) 50%,var(--gradient-4) 100%);
      -webkit-background-clip:text;
      -webkit-text-fill-color:transparent;
      background-clip:text;
      background-size:200% 200%;
      animation:ccGradientShift 8s ease infinite;
      letter-spacing:-.03em;
      margin-bottom:8px;
      line-height:1;
    }
    #cc-hero-module .stat-label{
      font-size:10px;
      font-weight:200;
      color:rgba(255,255,255,.25);
      letter-spacing:1.5px;
      text-transform:uppercase;
    }

    #cc-hero-module .scroll-hint{
      position:fixed;
      bottom:60px;
      left:80px;
      font-size:10px;
      font-weight:200;
      letter-spacing:1.5px;
      color:rgba(255,255,255,.25);
      text-transform:uppercase;
      z-index:4;
      writing-mode:vertical-rl;
      transform:rotate(180deg);
    }

    @keyframes ccFadeIn{
      from{opacity:0;transform:translateY(20px)}
      to{opacity:1;transform:translateY(0)}
    }

    @media(max-width:1200px){
      #cc-hero-module .hero{padding-top:120px}
      #cc-hero-module .hero-grid{grid-template-columns:1fr;gap:80px}
      #cc-hero-module .stats-sidebar{flex-direction:row;justify-content:space-between;gap:40px}
      #cc-hero-module .stat-item{text-align:center}
      #cc-hero-module .stat-number{font-size:2.8rem}
    }
    @media(max-width:768px){
      #cc-hero-module .hero{padding:100px 30px 60px}
      #cc-hero-module .badge{margin-bottom:25px;font-size:10px}
      #cc-hero-module h1{margin-bottom:30px}
      #cc-hero-module .subtitle{margin-bottom:35px;font-size:1rem}
      #cc-hero-module .service-tags{gap:20px;margin-bottom:35px}
      #cc-hero-module .tag{font-size:12px}
      #cc-hero-module .hero-cta{gap:30px}
      #cc-hero-module .cta-btn{font-size:13px}
      #cc-hero-module .stats-sidebar{flex-direction:column;gap:50px}
      #cc-hero-module .stat-number{font-size:2.5rem}
      #cc-hero-module .scroll-hint{left:30px;bottom:40px}
    }
    @media(max-width:480px){
      #cc-hero-module .hero{padding:80px 20px 40px}
      #cc-hero-module .hero-cta{flex-direction:column;gap:20px;align-items:flex-start}
    }

/* ==================== SERVICES REVEAL - OPTIMIZED ==================== */

.services-reveal {
  position: relative;
  min-height: 100vh;
  padding: 120px 0 150px;
  overflow: hidden;
  contain: layout style paint;
}

.services-reveal,
.services-reveal * {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif !important;
}

.services-reveal-container {
  max-width: 1600px;
  margin: 0 auto;
  padding: 0 80px;
  position: relative;
  z-index: 2;
}

/* ==================== HEADER ==================== */

.services-reveal-header {
  margin-bottom: 100px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  padding-bottom: 60px;
  max-width: 900px;
}

.services-reveal-label {
  display: block;
  font-size: 11px;
  font-weight: 200;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.35);
  margin-bottom: 30px;
}

.services-reveal-title {
  font-size: clamp(2.5rem, 5vw, 5rem);
  font-weight: 100;
  line-height: 1.3;
  letter-spacing: -0.04em;
  margin: 0 0 40px 0;
  padding-bottom: 20px;
  overflow: visible;
}

.services-reveal-word {
  display: block;
  background: linear-gradient(90deg, #667eea 0%, #764ba2 25%, #ec4899 50%, #f59e0b 75%, #667eea 100%);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: gradientFlow 8s linear infinite;
  will-change: transform, opacity;
}

@keyframes gradientFlow {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

.services-reveal-intro {
  font-size: clamp(1rem, 1.6vw, 1.3rem);
  font-weight: 100;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.4);
  margin: 0;
  letter-spacing: 0.01em;
  will-change: transform, opacity;
}

/* ==================== SERVICES LIST ==================== */

.services-reveal-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* ==================== SERVICE ITEM - GPU OPTIMIZED ==================== */

.service-reveal-item {
  display: grid;
  grid-template-columns: 80px 1fr;
  gap: 60px;
  padding: 60px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  position: relative;
  will-change: transform, opacity;
  transform: translateZ(0);
  backface-visibility: hidden;
}

.service-reveal-item:last-child {
  border-bottom: none;
}

/* Gradient line - GPU accelerated */
.service-reveal-item::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 1px;
  background: linear-gradient(90deg, #667eea 0%, #ec4899 50%, #f59e0b 100%);
  transition: width 1.2s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: width;
}

.service-reveal-item.active::before {
  width: 100%;
}

.service-reveal-number {
  font-size: 3rem;
  font-weight: 100;
  line-height: 1;
  background: linear-gradient(135deg, #764ba2 0%, #ec4899 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  will-change: transform, opacity;
}

.service-reveal-content {
  will-change: transform, opacity;
}

.service-reveal-name {
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  font-weight: 100;
  color: rgba(255, 255, 255, 0.9);
  margin: 0 0 20px 0;
  letter-spacing: -0.02em;
}

.service-reveal-desc {
  font-size: clamp(0.9rem, 1.2vw, 1rem);
  font-weight: 100;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.4);
  margin: 0 0 30px 0;
  letter-spacing: 0.01em;
}

.service-reveal-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.service-reveal-tags span {
  font-size: 13px;
  font-weight: 200;
  color: rgba(255, 255, 255, 0.3);
  letter-spacing: 0.3px;
  position: relative;
  padding-left: 14px;
}

.service-reveal-tags span::before {
  content: '•';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  color: #ec4899;
  opacity: 0.5;
}

/* Remove will-change after animation */
.service-reveal-item.animated {
  will-change: auto;
}

/* ==================== WHY IT MATTERS SECTION ==================== */

.services-why-matters {
  margin-top: 120px;
  padding-top: 80px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  max-width: 900px;
}

.why-matters-header {
  margin-bottom: 50px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.why-matters-label {
  display: block;
  font-size: 11px;
  font-weight: 200;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.35);
  margin-bottom: 25px;
}

.why-matters-title {
  font-size: clamp(1.8rem, 3vw, 2.8rem);
  font-weight: 100;
  line-height: 1.3;
  letter-spacing: -0.03em;
  margin: 0;
}

.why-matters-title-word {
  display: block;
  background: linear-gradient(90deg, #667eea 0%, #764ba2 25%, #ec4899 50%, #f59e0b 75%, #667eea 100%);
  background-size: 300% 300%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  animation: gradientFlow 8s linear infinite;
  will-change: transform, opacity;
}

.why-matters-content {
  will-change: transform, opacity;
}

.why-matters-text {
  font-size: clamp(0.95rem, 1.2vw, 1.08rem);
  font-weight: 100;
  line-height: 1.8;
  color: rgba(255, 255, 255, 0.65);
  margin: 0 0 28px 0;
  letter-spacing: 0.01em;
}

.why-matters-text:last-child {
  margin-bottom: 0;
}

.why-matters-link {
  color: rgba(255, 255, 255, 0.85);
  text-decoration: none;
  position: relative;
  font-weight: 200;
  transition: color 0.3s ease;
  background: linear-gradient(90deg, #ec4899, #f59e0b);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.why-matters-link::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -2px;
  width: 0;
  height: 1px;
  background: linear-gradient(90deg, #ec4899, #f59e0b);
  transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.why-matters-link:hover::after {
  width: 100%;
}

.why-matters-link:hover {
  background: linear-gradient(90deg, #f59e0b, #ec4899);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ==================== RESPONSIVE ==================== */

@media (max-width: 1024px) {
  .services-reveal-container {
    padding: 0 50px;
  }

  .service-reveal-item {
    grid-template-columns: 60px 1fr;
    gap: 40px;
  }

  .service-reveal-number {
    font-size: 2.5rem;
  }
}

@media (max-width: 768px) {
  .services-reveal {
    padding: 80px 0 100px;
  }

  .services-reveal-container {
    padding: 0 30px;
  }

  .services-reveal-header {
    margin-bottom: 60px;
    padding-bottom: 40px;
  }

  .service-reveal-item {
    grid-template-columns: 1fr;
    gap: 20px;
    padding: 40px 0;
  }

  .service-reveal-number {
    font-size: 2rem;
    will-change: auto; /* Disable scaling on mobile */
  }

  .service-reveal-name {
    font-size: 1.5rem;
  }

  .services-why-matters {
    margin-top: 80px;
    padding-top: 60px;
  }

  .why-matters-header {
    margin-bottom: 35px;
    padding-bottom: 30px;
  }

  .why-matters-label {
    margin-bottom: 20px;
  }

  .why-matters-title {
    font-size: 1.8rem;
  }

  .why-matters-text {
    margin-bottom: 22px;
  }
}

@media (max-width: 480px) {
  .services-reveal {
    padding: 60px 0 80px;
  }

  .services-reveal-container {
    padding: 0 20px;
  }

  .services-reveal-header {
    margin-bottom: 40px;
    padding-bottom: 30px;
  }

  .services-reveal-title {
    font-size: clamp(2rem, 8vw, 3rem);
    line-height: 1.4;
    padding-bottom: 15px;
    margin-bottom: 25px;
  }

  .services-reveal-intro {
    font-size: 0.95rem;
    line-height: 1.6;
  }

  .service-reveal-item {
    padding: 35px 0;
  }

  .service-reveal-number {
    font-size: 1.8rem;
    margin-bottom: 15px;
  }

  .service-reveal-name {
    font-size: 1.3rem;
    margin-bottom: 15px;
  }

  .service-reveal-desc {
    font-size: 0.9rem;
    margin-bottom: 20px;
  }

  .service-reveal-tags {
    gap: 12px;
  }

  .service-reveal-tags span {
    font-size: 12px;
  }

  .services-why-matters {
    margin-top: 60px;
    padding-top: 40px;
  }

  .why-matters-header {
    margin-bottom: 30px;
    padding-bottom: 25px;
  }

  .why-matters-label {
    font-size: 10px;
    letter-spacing: 2px;
    margin-bottom: 18px;
  }

  .why-matters-title {
    font-size: 1.5rem;
  }

  .why-matters-text {
    font-size: 0.92rem;
    line-height: 1.7;
    margin-bottom: 20px;
  }
}

/* ==================== PROCESS FLOW - LEFT ALIGNED ==================== */

.process-flow {
  position: relative !important;
  min-height: 100vh !important;
  padding: 120px 0 150px !important;
  overflow: hidden !important;
  background: transparent !important;
  margin: 0 !important;
}

.process-flow,
.process-flow *,
.process-flow *::before,
.process-flow *::after {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif !important;
  box-sizing: border-box !important;
}

.process-flow-container {
  max-width: 1600px !important;
  margin: 0 auto !important;
  padding: 0 80px !important;
  position: relative !important;
  z-index: 2 !important;
}

/* ==================== HEADER - LEFT ALIGNED ==================== */

.process-flow-header {
  margin-bottom: 80px !important;
  text-align: left !important;
  max-width: 100% !important;
}

.process-flow-label {
  display: block !important;
  font-size: 11px !important;
  font-weight: 200 !important;
  letter-spacing: 3px !important;
  text-transform: uppercase !important;
  color: rgba(255, 255, 255, 0.35) !important;
  margin: 0 0 25px 0 !important;
  padding: 0 !important;
  border: none !important;
  background: transparent !important;
  text-align: left !important;
}

.process-flow-title {
  font-size: clamp(2.5rem, 5vw, 4.5rem) !important;
  font-weight: 100 !important;
  line-height: 1.2 !important;
  letter-spacing: -0.04em !important;
  margin: 0 !important;
  padding: 0 !important;
  text-align: left !important;
}

/* Main Title Gradient Animation */
.process-flow-word {
  display: block !important;
  background: linear-gradient(270deg, #667eea, #764ba2, #ec4899, #f59e0b, #667eea) !important;
  background-size: 400% 400% !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
  -webkit-animation: processFlowMainGradient 8s ease infinite !important;
  animation: processFlowMainGradient 8s ease infinite !important;
  text-align: left !important;
}

@-webkit-keyframes processFlowMainGradient {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

@keyframes processFlowMainGradient {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* ==================== FLOW GRID - EQUAL HEIGHT ==================== */

.process-flow-grid {
  display: grid !important;
  grid-template-columns: repeat(4, 1fr) !important;
  gap: 30px !important;
  position: relative !important;
  align-items: stretch !important;
}

/* ==================== FLOW CARD - EQUAL HEIGHT ==================== */

.process-flow-card {
  position: relative !important;
  display: flex !important;
  align-items: stretch !important;
  will-change: transform, opacity !important;
  height: 100% !important;
}

.process-flow-card-inner {
  position: relative !important;
  background: rgba(255, 255, 255, 0.02) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  border-radius: 24px !important;
  padding: 50px 35px 40px !important;
  width: 100% !important;
  height: 100% !important;
  display: flex !important;
  flex-direction: column !important;
  transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1) !important;
  overflow: visible !important;
  margin: 0 !important;
}

.process-flow-card:hover .process-flow-card-inner {
  transform: translateY(-8px) !important;
  background: rgba(255, 255, 255, 0.04) !important;
  border-color: rgba(255, 255, 255, 0.15) !important;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4) !important;
}

/* ==================== NUMBER - HIGHLY VISIBLE ==================== */

.process-flow-number {
  position: absolute !important;
  top: -20px !important;
  left: 30px !important;
  width: 60px !important;
  height: 60px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
