/* ==================== CONTENT - LEFT ALIGNED WITH ANIMATED GRADIENT ==================== */

/* Card Title Gradient Animation */
.process-flow-card-title {
  font-size: clamp(1.3rem, 1.5vw, 1.6rem) !important;
  font-weight: 100 !important;
  margin: 0 0 20px 0 !important;
  padding: 0 !important;
  letter-spacing: -0.02em !important;
  line-height: 1.3 !important;
  text-align: left !important;
  background: linear-gradient(270deg, #667eea, #764ba2, #ec4899, #f59e0b, #667eea) !important;
  background-size: 400% 400% !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
  -webkit-animation: processFlowCardGradient 8s ease infinite !important;
  animation: processFlowCardGradient 8s ease infinite !important;
}

@-webkit-keyframes processFlowCardGradient {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

@keyframes processFlowCardGradient {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.process-flow-card-desc {
