  font-weight: 100 !important;
  line-height: 1.8 !important;
  color: rgba(255, 255, 255, 0.65) !important;
  margin: 0 !important;
  padding: 0 !important;
  letter-spacing: 0.01em !important;
  text-align: left !important;
  flex-grow: 1 !important;
}

.process-flow-link {
  color: rgba(255, 255, 255, 0.9) !important;
  text-decoration: none !important;
  position: relative !important;
  font-weight: 200 !important;
  background: linear-gradient(90deg, #ec4899, #f59e0b) !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
  transition: all 0.3s ease !important;
}

.process-flow-link::after {
  content: '' !important;
  position: absolute !important;
  left: 0 !important;
  bottom: -2px !important;
  width: 0 !important;
  height: 1px !important;
  background: linear-gradient(90deg, #ec4899, #f59e0b) !important;
  transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1) !important;
}

.process-flow-link:hover::after {
  width: 100% !important;
}

/* ==================== CONNECTION ARROW ==================== */

.process-flow-arrow {
  position: absolute !important;
  right: -30px !important;
  top: 50% !important;
  width: 60px !important;
  height: 2px !important;
  transform: translateY(-50%) !important;
  z-index: 5 !important;
  opacity: 0 !important;
  transition: opacity 0.8s ease !important;
  margin: 0 !important;
  padding: 0 !important;
}

.process-flow-card.animated .process-flow-arrow {
  opacity: 1 !important;
}

.process-flow-arrow svg {
  width: 100% !important;
  height: 100% !important;
  display: block !important;
}

.process-flow-arrow svg line {
  animation: dash 2s linear infinite !important;
}

@keyframes dash {
  to {
    stroke-dashoffset: -20;
  }
}

.process-flow-arrow-head {
  position: absolute !important;
  right: -8px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  font-size: 1.5rem !important;
  background: linear-gradient(90deg, #ec4899, #f59e0b) !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
  font-weight: 300 !important;
  animation: arrowPulse 2s ease-in-out infinite !important;
  line-height: 1 !important;
}

@keyframes arrowPulse {
  0%, 100% { transform: translateY(-50%) translateX(0); opacity: 1; }
  50% { transform: translateY(-50%) translateX(5px); opacity: 0.7; }
}

.process-flow-card:last-child .process-flow-arrow {
  display: none !important;
}

