  color: rgba(255,255,255,.70) !important;
}

.proofB__title{
  margin:0 0 12px 0 !important;
  font-size: clamp(2.2rem, 4.3vw, 4rem) !important;
  font-weight:200 !important;
  letter-spacing:-0.05em !important;
  line-height:1.05 !important;
  color: rgba(255,255,255,.98) !important;
}

.proofB__titleGlow{
  display:inline-block !important;
  background: var(--grad) !important;
  background-size: 300% 300% !important;
  -webkit-background-clip:text !important;
  background-clip:text !important;
  -webkit-text-fill-color:transparent !important;
  animation: proofBFlow 10s linear infinite !important;
  filter: drop-shadow(0 14px 35px rgba(236,72,153,0.12)) !important;
}

@keyframes proofBFlow{
  0%,100%{ background-position: 0% 50%; }
  50%{ background-position: 100% 50%; }
}

.proofB__sub{
  margin:0 0 18px 0 !important;
  font-size: clamp(1rem, 1.25vw, 1.15rem) !important;
  font-weight:200 !important;
  line-height:1.65 !important;
