/* ===================== CHIPS ===================== */
.proofB__chips{
  display:flex !important;
  flex-wrap:wrap !important;
  gap:12px !important;
  margin-top: 14px !important;
  position:relative !important;
  z-index: 10 !important;
  background: transparent !important;
  isolation: isolate !important;
}

.proofB__chip{
  all: unset !important;
  box-sizing:border-box !important;
  display:inline-flex !important;
  align-items:center !important;
  justify-content:center !important;
  cursor:pointer !important;
  user-select:none !important;

  height: 46px !important;
  padding: 0 18px !important;
  border-radius: 999px !important;
  position: relative !important;
  isolation: isolate !important;

  color: rgba(255,255,255,.70) !important;
  font-weight: 300 !important;
  font-size: 14px !important;

  transition: transform .18s ease, filter .18s ease, color .18s ease !important;
}

.proofB__chip::after{
  content:"" !important;
  position:absolute !important;
  inset: 1px !important;
  border-radius: inherit !important;
  background: rgba(10,12,18,.55) !important;
  backdrop-filter: blur(14px) !important;
  z-index: -1 !important;
  transition: background .18s ease !important;
}

.proofB__chip::before{
  content:"" !important;
  position:absolute !important;
  inset: 0 !important;
  border-radius: inherit !important;
  padding: 1px !important;
  background: var(--grad) !important;
  background-size: 320% 320% !important;
  animation: proofChipFlow 10s linear infinite !important;

  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0) !important;
  -webkit-mask-composite: xor !important;
  mask-composite: exclude !important;

  opacity: .60 !important;
  z-index: -2 !important;
  transition: opacity .18s ease, filter .18s ease !important;
}

@keyframes proofChipFlow{
  0%,100%{ background-position: 0% 50%; }
  50%{ background-position: 100% 50%; }
}

.proofB__chip:hover{
  transform: translateY(-1px) !important;
  color: rgba(255,255,255,.92) !important;
}
.proofB__chip:hover::before{ opacity: .85 !important; }
.proofB__chip:hover::after{ background: rgba(10,12,18,.70) !important; }

.proofB__chip.is-active{
  color: rgba(255,255,255,.92) !important;
  transform: translateY(-1px) !important;
  box-shadow: 0 16px 44px rgba(0,0,0,.45) !important;
}
.proofB__chip.is-active::before{ opacity: 1 !important; }
.proofB__chip.is-active::after{ background: rgba(8,10,16,.72) !important; }

.proofB__chipText{ position: relative !important; z-index: 2 !important; }

/* ===================== GRID + TILES ===================== */
.proofB__grid{
  display:grid !important;
  gap:18px !important;
  grid-template-columns: repeat(12, 1fr) !important;
  grid-auto-rows: minmax(140px, auto) !important;
  margin-top: 22px !important;
